/// Read one clause line of a command body.
fn parse_clause(stream: &mut Stream, body: &mut Body, name: &str) -> Result<(), ParseError> {
    let Some(token) = stream.peek() else {
        return Err(ParseError::new(
            stream.peek_span(),
