    assert_eq!(
        POSITIONAL_WORDS,
        [
            SEND_WORD,
            TO_WORD,
            QUERY_WORD,
            ANSWER_WORD,
            RUN_WORD,
            IN_WORD,
            COMMAND_WORD,
            PROGRAM_WORD,
            ADMITS_WORD,
            REFUSES_WORD,
            SPECIMEN_WORD,
            OPTION_WORD,
            OPERAND_WORD,
            ENV_WORD,
            CWD_WORD,
