        record.completeness
    );
    assert!(
        record.rendered().contains("completeness:"),
        "the rendered record must carry the claim a reader checks"
    );
    assert_eq!(
        record.correction_digest.len(),
        64,
        "the record names what it swept against by digest"
    );
}

