/// A RESTORE that is not byte-exact refuses. Restoration is BYTE-COMPARED,
/// never assumed — L6's own rule.
#[test]
fn an_inexact_restoration_refuses() {
    let parsed = checked(&document(&format!(
        "artifact hazard_step \"scripts/hazard.sh\"\n  digest \"{}\"\n  \
         restores \".fleet/gate-entry.sh\"\n\n\
         recipe run_hazard\n  step fire_it\n    fires artifact hazard_step expecting \"restored\"",
        digest_of(b"#!/bin/sh\n")
    )));
    let tree_bytes = StatedTree::new()
        .with("scripts/hazard.sh", "#!/bin/sh\n")
        .with(".fleet/gate-entry.sh", GATE_BYTES);
    // The firer answers correctly AND the restoration is spoiled while it
    // runs, which is exactly the case a byte-compare exists to catch.
    struct Spoiling<'a>(&'a StatedTree);
    impl aion_awl::command::recipe::SpecimenFirer for Spoiling<'_> {
        fn fire(
            &self,
            _address: &str,
        ) -> Result<aion_awl::command::recipe::VerdictRecord, String> {
            self.0
                .rewrite(".fleet/gate-entry.sh", "#!/bin/sh\n# a line the hazard left behind\n");
            aion_awl::command::recipe::VerdictRecord::new("restored", "gate", "ok")
                .map_err(|error| error.to_string())
        }
    }
    let fired = fire(
        &parsed.recipes[0],
        &parsed.artifacts,
        &compose(&parsed.recipes[0], &Composition::new()).expect("no slots"),
        &Preconditions::new(),
        tree(),
        &tree_bytes,
        &Spoiling(&tree_bytes),
    )
    .expect("the receipt is buildable");
    let refusal = fired.refusal.expect("an inexact restoration must refuse");
    assert_eq!(refusal.cause(), CommandCause::RestoreInexact);
    assert!(
        refusal.message().contains(&digest_of(GATE_BYTES.as_bytes())),
        "the refusal must carry the digest the bytes had BEFORE the fire; got: {}",
        refusal.message()
    );
}

