    artifacts: &[ArtifactDecl],
    values: &BTreeMap<String, String>,
    ports: &Ports<'_>,
    receipt: &mut Receipt,
) -> Option<CommandRefusal> {
    let Ok(ordered) = topological_order(recipe) else {
